import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");
        String format = req.getParameter("fmt");

        if (reportType == null || dateRange == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate report type against allowed list
        List<String> allowedTypes = Arrays.asList("sales", "inventory", "payroll", "audit");
        if (!allowedTypes.contains(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Build query - department filter is optional
        String query = buildQuery(reportType, dateRange, department);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print(resultSetToJson(rs));

        } catch (SQLException e) {
            // Log full error for debugging
            log("Query failed: " + query + " Error: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildQuery(String reportType, String dateRange, String department) {
        // reportType is validated above, dateRange uses prepared mapping
        String dateClause = getDateClause(dateRange);
        String baseQuery = String.format(
            "SELECT * FROM reports_%s WHERE %s", reportType, dateClause);

        // Department filter - user controlled, appended directly
        if (department != null && !department.isEmpty()) {
            baseQuery += " AND department = '" + department + "'";
        }

        return baseQuery;
    }

    private String getDateClause(String range) {
        // Even though range is user-controlled, we map to fixed clauses
        switch (range) {
            case "today": return "report_date = CURRENT_DATE";
            case "week": return "report_date >= CURRENT_DATE - INTERVAL '7 days'";
            case "month": return "report_date >= CURRENT_DATE - INTERVAL '30 days'";
            case "quarter": return "report_date >= CURRENT_DATE - INTERVAL '90 days'";
            default: return "report_date >= CURRENT_DATE - INTERVAL '30 days'";
        }
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        StringBuilder sb = new StringBuilder("[");
        boolean first = true;
        while (rs.next()) {
            if (!first) sb.append(",");
            sb.append("{");
            for (int i = 1; i <= cols; i++) {
                if (i > 1) sb.append(",");
                sb.append("\"").append(meta.getColumnName(i)).append("\":");
                String val = rs.getString(i);
                sb.append(val == null ? "null" : "\"" + val.replace("\"", "\\\"") + "\"");
            }
            sb.append("}");
            first = false;
        }
        sb.append("]");
        return sb.toString();
    }
}
